const HTML = "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<meta name=\"description\" content=\"See who doesn't follow you back on Instagram, using your own data export. Everything runs in your browser.\">\n<title>Follow Check</title>\n<meta property=\"og:type\" content=\"website\">\n<meta property=\"og:site_name\" content=\"Follow Check\">\n<meta property=\"og:title\" content=\"Follow Check\">\n<meta property=\"og:description\" content=\"See who doesn't follow you back on Instagram. Runs in your browser, nothing uploaded.\">\n<meta property=\"og:url\" content=\"https://thefollowcheck.com/\">\n<meta property=\"og:image\" content=\"https://thefollowcheck.com/og.png\">\n<meta property=\"og:image:width\" content=\"1200\">\n<meta property=\"og:image:height\" content=\"630\">\n<meta name=\"twitter:card\" content=\"summary_large_image\">\n<link rel=\"icon\" href=\"/favicon.svg\" type=\"image/svg+xml\">\n<link rel=\"apple-touch-icon\" href=\"/apple-touch-icon.png\">\n<link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n<link rel=\"preconnect\" href=\"https://fonts.gstatic.com\" crossorigin>\n<link href=\"https://fonts.googleapis.com/css2?family=Bricolage+Grotesque:opsz,wght@12..96,600;12..96,700&family=IBM+Plex+Sans:wght@400;500;600&display=swap\" rel=\"stylesheet\">\n<style>\n/* one narrow column: summary tiles that double as tabs, then the list, then the loader */\n:root {\n  --bg: #eef1f4;\n  --surface: #ffffff;\n  --ink: #141a20;\n  --dim: #5b6977;\n  --line: #d9e0e6;\n  --accent: #2b62c9;\n  --bad: #c9304a;\n  --warn: #b07800;\n  --good: #198a57;\n  --gone: #6f7c88;\n  --display: \"Bricolage Grotesque\", \"Avenir Next\", system-ui, sans-serif;\n  --body: \"IBM Plex Sans\", -apple-system, \"Segoe UI\", system-ui, sans-serif;\n  color-scheme: light;\n}\n@media (prefers-color-scheme: dark) {\n  :root:not([data-theme=\"light\"]) {\n    --bg: #0f1316; --surface: #171d22; --ink: #e6ebef; --dim: #8b98a3; --line: #263038;\n    --accent: #79a6ff; --bad: #ff7a8a; --warn: #ffb454; --good: #5dd39e; --gone: #8b98a3;\n    color-scheme: dark;\n  }\n}\n:root[data-theme=\"dark\"] {\n  --bg: #0f1316; --surface: #171d22; --ink: #e6ebef; --dim: #8b98a3; --line: #263038;\n  --accent: #79a6ff; --bad: #ff7a8a; --warn: #ffb454; --good: #5dd39e; --gone: #8b98a3;\n  color-scheme: dark;\n}\n\n* { box-sizing: border-box; }\nhtml, body { margin: 0; }\nbody {\n  background: var(--bg);\n  color: var(--ink);\n  font: 400 15px/1.5 var(--body);\n  -webkit-text-size-adjust: 100%;\n}\n.wrap { max-width: 640px; margin: 0 auto; padding: 24px 16px 48px; display: grid; gap: 20px; }\n\nheader { display: grid; gap: 4px; }\nh1 { font: 700 30px/1.1 var(--display); margin: 0; letter-spacing: -0.01em; text-wrap: balance; }\nh2 { font: 600 19px/1.2 var(--display); margin: 0; text-wrap: balance; }\n.lede { color: var(--dim); margin: 0; max-width: 60ch; }\n.meta { color: var(--dim); font-size: 13px; font-variant-numeric: tabular-nums; }\n\n.banner {\n  border: 1px dashed var(--warn);\n  color: var(--ink);\n  background: color-mix(in srgb, var(--warn) 10%, var(--surface));\n  border-radius: 10px;\n  padding: 10px 12px;\n  font-size: 14px;\n}\n.banner[hidden] { display: none; }\n\n.tiles { display: grid; grid-template-columns: repeat(2, 1fr); gap: 10px; }\n@media (min-width: 560px) { .tiles { grid-template-columns: repeat(4, 1fr); } }\n.tile {\n  appearance: none;\n  text-align: left;\n  font: inherit;\n  color: inherit;\n  background: var(--surface);\n  border: 1px solid var(--line);\n  border-left: 4px solid var(--c);\n  border-radius: 10px;\n  padding: 10px 12px;\n  cursor: pointer;\n  display: grid;\n  gap: 2px;\n}\n.tile .n { font: 700 26px/1 var(--display); font-variant-numeric: tabular-nums; color: var(--c); }\n.tile .l { font-size: 13px; color: var(--dim); line-height: 1.3; }\n.tile[aria-pressed=\"true\"] { background: color-mix(in srgb, var(--c) 12%, var(--surface)); border-color: var(--c); }\n.tile:focus-visible, button:focus-visible, a:focus-visible, input:focus-visible, select:focus-visible, .drop:focus-within {\n  outline: 2px solid var(--accent); outline-offset: 2px;\n}\n\n.panel { background: var(--surface); border: 1px solid var(--line); border-radius: 12px; overflow: hidden; }\n.panel-head { display: grid; gap: 10px; padding: 14px 14px 12px; border-bottom: 1px solid var(--line); }\n.panel-title { display: flex; align-items: baseline; justify-content: space-between; gap: 12px; }\n.hint { color: var(--dim); font-size: 13px; margin: 0; }\n.controls { display: flex; gap: 8px; }\n.controls input, .controls select {\n  font: inherit; font-size: 16px; color: var(--ink); background: var(--bg);\n  border: 1px solid var(--line); border-radius: 8px; padding: 8px 10px; min-width: 0;\n}\n.controls input { flex: 1; }\n\nul.list { list-style: none; margin: 0; padding: 0; }\n.row { display: flex; align-items: center; gap: 10px; padding: 10px 14px; border-bottom: 1px solid var(--line); }\n.row:last-child { border-bottom: 0; }\n.who { flex: 1; min-width: 0; display: grid; }\n.who .u { font-weight: 500; overflow-wrap: anywhere; }\n.who .s { font-size: 12px; color: var(--dim); font-variant-numeric: tabular-nums; }\n.row .old { color: var(--warn); }\n.btn {\n  appearance: none; font: 500 13px/1 var(--body); text-decoration: none; white-space: nowrap;\n  color: var(--accent); background: transparent; border: 1px solid var(--line);\n  border-radius: 999px; padding: 8px 12px; cursor: pointer;\n}\n.btn.mark { color: var(--dim); }\n.btn.primary { background: var(--accent); color: var(--surface); border-color: var(--accent); }\n.empty { padding: 28px 14px; text-align: center; color: var(--dim); }\n\n.loader { padding: 14px; display: grid; gap: 12px; }\n.loader ol { margin: 0; padding-left: 20px; color: var(--dim); font-size: 14px; display: grid; gap: 4px; }\n.loader ol b { color: var(--ink); font-weight: 500; }\n.drop {\n  border: 2px dashed var(--line); border-radius: 12px; padding: 20px 14px;\n  display: grid; gap: 8px; justify-items: center; text-align: center; cursor: pointer;\n}\n.drop.over { border-color: var(--accent); background: color-mix(in srgb, var(--accent) 8%, var(--surface)); }\n.drop input { position: absolute; width: 1px; height: 1px; opacity: 0; }\n.status { font-size: 14px; margin: 0; }\n.status.err { color: var(--bad); }\n.status.ok { color: var(--good); }\n.foot { display: flex; justify-content: space-between; align-items: center; gap: 12px; flex-wrap: wrap; }\n.privacy { font-size: 13px; color: var(--dim); margin: 0; }\n\n@media (prefers-reduced-motion: no-preference) {\n  .tile, .btn { transition: background-color .15s, border-color .15s; }\n}\n</style>\n</head>\n<body>\n<div class=\"wrap\">\n  <header>\n    <h1>Follow Check</h1>\n    <p class=\"lede\">See who doesn't follow you back on Instagram, using your own data export. Everything runs in this browser. Nothing is uploaded.</p>\n    <span class=\"meta\" id=\"meta\"></span>\n  </header>\n\n  <div class=\"banner\" id=\"demo\" hidden>You're looking at example accounts. Load your export below to see your own.</div>\n\n  <div class=\"tiles\" role=\"group\" aria-label=\"Lists\">\n    <button class=\"tile\" id=\"t-notBack\" style=\"--c: var(--bad)\" aria-pressed=\"true\"><span class=\"n\" id=\"n-notBack\">0</span><span class=\"l\">Not following back</span></button>\n    <button class=\"tile\" id=\"t-fans\" style=\"--c: var(--warn)\" aria-pressed=\"false\"><span class=\"n\" id=\"n-fans\">0</span><span class=\"l\">Fans you don't follow</span></button>\n    <button class=\"tile\" id=\"t-mutual\" style=\"--c: var(--good)\" aria-pressed=\"false\"><span class=\"n\" id=\"n-mutual\">0</span><span class=\"l\">Mutuals</span></button>\n    <button class=\"tile\" id=\"t-gone\" style=\"--c: var(--gone)\" aria-pressed=\"false\"><span class=\"n\" id=\"n-gone\">0</span><span class=\"l\">Marked gone</span></button>\n  </div>\n\n  <section class=\"panel\" aria-labelledby=\"list-title\">\n    <div class=\"panel-head\">\n      <div class=\"panel-title\">\n        <h2 id=\"list-title\">Not following back</h2>\n        <span class=\"meta\" id=\"list-count\"></span>\n      </div>\n      <p class=\"hint\" id=\"list-hint\"></p>\n      <div class=\"controls\">\n        <input id=\"q\" type=\"search\" placeholder=\"Search usernames\" autocomplete=\"off\" autocapitalize=\"none\" spellcheck=\"false\" aria-label=\"Search usernames\">\n        <select id=\"sort\" aria-label=\"Sort\">\n          <option value=\"az\">A\u2013Z</option>\n          <option value=\"old\">Oldest first</option>\n          <option value=\"new\">Newest first</option>\n        </select>\n      </div>\n    </div>\n    <ul class=\"list\" id=\"list\"></ul>\n  </section>\n\n  <section class=\"panel\" aria-labelledby=\"load-title\">\n    <div class=\"loader\">\n      <h2 id=\"load-title\">Load your export</h2>\n      <ol>\n        <li>In Instagram, open <b>Accounts Center \u2192 Your information and permissions \u2192 Export your information</b>.</li>\n        <li>Choose <b>Followers and following</b> only, format <b>JSON</b>.</li>\n        <li>When it's ready, drop the .zip here, or pick <b>followers_1.json</b> and <b>following.json</b>.</li>\n      </ol>\n      <label class=\"drop\" id=\"drop\" for=\"file\">\n        <input id=\"file\" type=\"file\" multiple>\n        <span class=\"btn primary\">Choose files</span>\n        <span class=\"hint\">or drag the .zip or .json files here</span>\n      </label>\n      <p class=\"status\" id=\"status\" role=\"status\"></p>\n      <div class=\"foot\">\n        <p class=\"privacy\">Saved only in this browser on this device.</p>\n        <button class=\"btn mark\" id=\"clear\" type=\"button\">Clear saved data</button>\n      </div>\n    </div>\n  </section>\n</div>\n\n<script>\nconst KEY = \"followcheck.v1\";\nconst VIEWS = {\n  notBack: { title: \"Not following back\", hint: \"Accounts you follow that don't follow you. Tap Mark gone for ones that are deactivated or deleted.\", markable: true, since: \"You followed\" },\n  fans: { title: \"Fans you don't follow\", hint: \"Accounts that follow you that you don't follow back.\", markable: false, since: \"Followed you\" },\n  mutual: { title: \"Mutuals\", hint: \"You follow each other.\", markable: false, since: \"You followed\" },\n  gone: { title: \"Marked gone\", hint: \"Accounts you marked as deactivated. Marks clear on their own if they follow you again or you unfollow them.\", markable: true, since: \"You followed\" }\n};\n\n// ---------- persistence ----------\nfunction loadSaved() {\n  try { return JSON.parse(localStorage.getItem(KEY)); } catch (e) { return null; }\n}\nfunction save(d) {\n  try { localStorage.setItem(KEY, JSON.stringify(d)); return true; } catch (e) { return false; }\n}\n\n// ---------- example data ----------\nfunction makeDemo() {\n  const day = 86400, now = Math.floor(Date.now() / 1000);\n  const f = (u, d) => ({ username: u, timestamp: now - d * day });\n  const following = [\n    f(\"example.coffee.lab\", 40), f(\"example.trailrunner\", 900), f(\"example.dad.jokes\", 1400),\n    f(\"example.mlb.stats\", 120), f(\"example.oldfriend\", 2100), f(\"example.chef.mo\", 300),\n    f(\"example.sneakers\", 700), f(\"example.cousin.j\", 1600), f(\"example.hoops.daily\", 60),\n    f(\"example.photo.walks\", 450)\n  ];\n  const followers = [\n    f(\"example.chef.mo\", 280), f(\"example.cousin.j\", 1500), f(\"example.hoops.daily\", 55),\n    f(\"example.photo.walks\", 430), f(\"example.sneakers\", 650), f(\"example.gym.buddy\", 30),\n    f(\"example.bookclub\", 200), f(\"example.neighbor\", 800), f(\"example.fan.account\", 15),\n    f(\"example.tacos\", 365), f(\"example.music.picks\", 90)\n  ];\n  return { followers, following, gone: [\"example.oldfriend\"], savedAt: Date.now(), demo: true };\n}\n\n// ---------- parse Instagram JSON ----------\nfunction extractUsers(data) {\n  let arr = Array.isArray(data) ? data : [];\n  if (!Array.isArray(data) && data) {\n    const k = Object.keys(data).find(k => Array.isArray(data[k]));\n    if (k) arr = data[k];\n  }\n  return arr.map(u => {\n    const s = (u.string_list_data && u.string_list_data[0]) || {};\n    let name = s.value || u.title || null;\n    if (!name && s.href) {\n      const m = s.href.match(/instagram\\.com\\/(?:_u\\/)?([^/?#]+)/);\n      if (m) name = m[1];\n    }\n    return name ? { username: name, timestamp: s.timestamp || null } : null;\n  }).filter(Boolean);\n}\n\nfunction kindOf(name, data) {\n  if (/(^|\\/)followers[^/]*\\.json$/i.test(name)) return \"followers\";\n  if (/(^|\\/)following[^/]*\\.json$/i.test(name)) return \"following\";\n  const keys = data && !Array.isArray(data) ? Object.keys(data).join(\" \") : \"\";\n  if (/following/i.test(keys)) return \"following\";\n  if (/followers/i.test(keys)) return \"followers\";\n  if (/following/i.test(name)) return \"following\";\n  if (/followers/i.test(name)) return \"followers\";\n  return null;\n}\n\n// ---------- minimal zip reader (reads only the entries it needs) ----------\nfunction u64(dv, o) { return dv.getUint32(o, true) + dv.getUint32(o + 4, true) * 2 ** 32; }\n\nasync function view(file, start, end) {\n  return new DataView(await file.slice(start, end).arrayBuffer());\n}\n\nasync function readZip(file, want) {\n  const size = file.size;\n  const tailLen = Math.min(size, 65557);\n  const tail = await view(file, size - tailLen, size);\n  let eocd = -1;\n  for (let i = tailLen - 22; i >= 0; i--) {\n    if (tail.getUint32(i, true) === 0x06054b50) { eocd = i; break; }\n  }\n  if (eocd < 0) throw new Error(\"That .zip couldn't be read. Try downloading the export again.\");\n\n  let count = tail.getUint16(eocd + 10, true);\n  let cdSize = tail.getUint32(eocd + 12, true);\n  let cdOff = tail.getUint32(eocd + 16, true);\n  if (count === 0xffff || cdSize === 0xffffffff || cdOff === 0xffffffff) {\n    const loc = eocd - 20;\n    if (loc >= 0 && tail.getUint32(loc, true) === 0x07064b50) {\n      const zOff = u64(tail, loc + 8);\n      const z = await view(file, zOff, zOff + 56);\n      if (z.getUint32(0, true) === 0x06064b50) {\n        count = u64(z, 32); cdSize = u64(z, 40); cdOff = u64(z, 48);\n      }\n    }\n  }\n\n  const cd = await view(file, cdOff, cdOff + cdSize);\n  const dec = new TextDecoder();\n  const hits = [];\n  let p = 0;\n  for (let i = 0; i < count && p + 46 <= cd.byteLength; i++) {\n    if (cd.getUint32(p, true) !== 0x02014b50) break;\n    const method = cd.getUint16(p + 10, true);\n    let comp = cd.getUint32(p + 20, true);\n    const unc = cd.getUint32(p + 24, true);\n    const nLen = cd.getUint16(p + 28, true), xLen = cd.getUint16(p + 30, true), cLen = cd.getUint16(p + 32, true);\n    let local = cd.getUint32(p + 42, true);\n    const name = dec.decode(new Uint8Array(cd.buffer, cd.byteOffset + p + 46, nLen));\n\n    if (want(name)) {\n      if (comp === 0xffffffff || local === 0xffffffff) {\n        let x = p + 46 + nLen;\n        const end = x + xLen;\n        while (x + 4 <= end) {\n          const id = cd.getUint16(x, true), sz = cd.getUint16(x + 2, true);\n          if (id === 1) {\n            let q = x + 4;\n            if (unc === 0xffffffff) q += 8;\n            if (comp === 0xffffffff) { comp = u64(cd, q); q += 8; }\n            if (local === 0xffffffff) local = u64(cd, q);\n            break;\n          }\n          x += 4 + sz;\n        }\n      }\n      hits.push({ name, method, comp, local });\n    }\n    p += 46 + nLen + xLen + cLen;\n  }\n\n  const out = [];\n  for (const h of hits) {\n    if (!/\\.json$/i.test(h.name)) { out.push({ name: h.name, text: null }); continue; }\n    const lh = await view(file, h.local, h.local + 30);\n    const start = h.local + 30 + lh.getUint16(26, true) + lh.getUint16(28, true);\n    const blob = file.slice(start, start + h.comp);\n    let text;\n    if (h.method === 0) text = await blob.text();\n    else if (h.method === 8) {\n      if (typeof DecompressionStream === \"undefined\") throw new Error(\"This browser can't open .zip files. Unzip the export and pick the two .json files instead.\");\n      text = await new Response(blob.stream().pipeThrough(new DecompressionStream(\"deflate-raw\"))).text();\n    } else throw new Error(\"That .zip uses a format this page can't open. Unzip it and pick the two .json files instead.\");\n    out.push({ name: h.name, text });\n  }\n  return out;\n}\n\n// ---------- load files ----------\nlet pending = null;\n\nasync function handleFiles(files) {\n  if (!pending) pending = { followers: new Map(), following: new Map(), sawFollowers: false, sawFollowing: false };\n  const { followers, following } = pending;\n  let sawHtml = false;\n  const skipped = [];\n\n  function add(name, text) {\n    let data;\n    try { data = JSON.parse(text.replace(/^\\uFEFF/, \"\")); } catch (e) { skipped.push(name + \" (not readable JSON)\"); return; }\n    const kind = kindOf(name, data);\n    if (!kind) { skipped.push(name); return; }\n    const target = kind === \"following\" ? following : followers;\n    for (const u of extractUsers(data)) if (!target.has(u.username)) target.set(u.username, u);\n    if (kind === \"following\") pending.sawFollowing = true; else pending.sawFollowers = true;\n  }\n\n  setStatus(\"Reading\u2026\");\n  try {\n    for (const f of files) {\n      const n = f.name.toLowerCase();\n      if (n.endsWith(\".zip\")) {\n        const entries = await readZip(f, name => /(^|\\/)(followers_\\d+|following)\\.(json|html)$/i.test(name));\n        for (const e of entries) {\n          if (e.text === null) sawHtml = true;\n          else add(e.name, e.text);\n        }\n      } else if (n.endsWith(\".json\")) {\n        add(f.name, await f.text());\n      } else {\n        skipped.push(f.name);\n      }\n    }\n  } catch (e) {\n    setStatus(e.message || \"Couldn't read those files.\", \"err\");\n    return;\n  }\n\n  const { sawFollowers, sawFollowing } = pending;\n  if (!sawFollowers || !sawFollowing) {\n    let msg;\n    if (sawHtml && !sawFollowers && !sawFollowing) msg = \"That export is in HTML format. Request a new export and choose JSON.\";\n    else if (sawFollowers) msg = `Got ${followers.size} followers. Now choose following.json.`;\n    else if (sawFollowing) msg = `Got ${following.size} following. Now choose followers_1.json.`;\n    else msg = \"No follower files found. Pick the export .zip, or followers_1.json and following.json.\";\n    if (skipped.length) msg += \" Couldn't use: \" + skipped.join(\", \") + \".\";\n    setStatus(msg, \"err\");\n    return;\n  }\n\n  pending = null;\n  const prev = state.demo ? null : state;\n  const fl = [...followers.values()], fg = [...following.values()];\n  state = { followers: fl, following: fg, gone: pruneGone(prev && prev.gone, fl, fg), savedAt: Date.now() };\n  const stored = save(state);\n  setStatus(\n    `Loaded ${fl.length} followers and ${fg.length} following.` + (stored ? \"\" : \" This browser won't keep it after you close the page.\"),\n    \"ok\"\n  );\n  render();\n}\n\n// keep a mark only while you still follow the account and it still doesn't\n// follow you; following you again means it was reactivated\nfunction pruneGone(gone, followers, following) {\n  if (!gone) return [];\n  const fSet = new Set(followers.map(u => u.username));\n  const gSet = new Set(following.map(u => u.username));\n  return gone.filter(n => gSet.has(n) && !fSet.has(n));\n}\n\nfunction toggleGone(username) {\n  const gone = new Set(state.gone || []);\n  if (gone.has(username)) gone.delete(username);\n  else gone.add(username);\n  state.gone = [...gone];\n  if (!state.demo) save(state);\n  render();\n}\n\n// ---------- compare ----------\nfunction compare(d) {\n  const fSet = new Set(d.followers.map(u => u.username));\n  const gSet = new Set(d.following.map(u => u.username));\n  const goneSet = new Set(d.gone || []);\n  return {\n    notBack: d.following.filter(u => !fSet.has(u.username) && !goneSet.has(u.username)),\n    fans: d.followers.filter(u => !gSet.has(u.username)),\n    mutual: d.following.filter(u => fSet.has(u.username)),\n    gone: d.following.filter(u => goneSet.has(u.username))\n  };\n}\n\n// ---------- render ----------\nlet state = loadSaved();\nif (!state || !state.followers || !state.following) state = makeDemo();\nlet current = \"notBack\";\n\nconst $ = id => document.getElementById(id);\nconst fmtDate = ts => new Date(ts * 1000).toLocaleDateString(undefined, { year: \"numeric\", month: \"short\", day: \"numeric\" });\n\nfunction ago(ts) {\n  const days = (Date.now() / 1000 - ts) / 86400;\n  if (days < 1) return \"today\";\n  if (days < 31) return Math.floor(days) + \"d ago\";\n  if (days < 365) return Math.floor(days / 30.4) + \"mo ago\";\n  return Math.floor(days / 365) + \"y ago\";\n}\n\nfunction setStatus(msg, kind) {\n  const s = $(\"status\");\n  s.textContent = msg || \"\";\n  s.className = \"status\" + (kind ? \" \" + kind : \"\");\n}\n\nfunction render() {\n  const r = compare(state);\n  $(\"demo\").hidden = !state.demo;\n  $(\"meta\").textContent =\n    `Following ${state.following.length} \u00b7 Followers ${state.followers.length}` +\n    (state.demo ? \"\" : ` \u00b7 Updated ${new Date(state.savedAt).toLocaleDateString()}`);\n\n  for (const k of Object.keys(VIEWS)) {\n    $(\"n-\" + k).textContent = r[k].length;\n    $(\"t-\" + k).setAttribute(\"aria-pressed\", k === current ? \"true\" : \"false\");\n  }\n\n  const v = VIEWS[current];\n  $(\"list-title\").textContent = v.title;\n  $(\"list-hint\").textContent = v.hint;\n\n  const q = $(\"q\").value.trim().toLowerCase().replace(/^@/, \"\");\n  const sort = $(\"sort\").value;\n  let items = r[current].filter(u => !q || u.username.toLowerCase().includes(q));\n  if (sort === \"az\") items.sort((a, b) => a.username.localeCompare(b.username));\n  else {\n    const dir = sort === \"old\" ? 1 : -1;\n    items.sort((a, b) => ((a.timestamp || 0) - (b.timestamp || 0)) * dir);\n  }\n  $(\"list-count\").textContent = items.length === r[current].length\n    ? `${items.length} ${items.length === 1 ? \"account\" : \"accounts\"}`\n    : `${items.length} of ${r[current].length}`;\n\n  const list = $(\"list\");\n  list.replaceChildren();\n  if (!items.length) {\n    const li = document.createElement(\"li\");\n    li.className = \"empty\";\n    li.textContent = q ? \"No usernames match that search.\" : \"Nobody here.\";\n    list.append(li);\n    return;\n  }\n\n  for (const u of items) {\n    const li = document.createElement(\"li\");\n    li.className = \"row\";\n\n    const who = document.createElement(\"div\");\n    who.className = \"who\";\n    const name = document.createElement(\"span\");\n    name.className = \"u\";\n    name.textContent = \"@\" + u.username;\n    who.append(name);\n    if (u.timestamp) {\n      const s = document.createElement(\"span\");\n      s.className = \"s\";\n      const age = document.createElement(\"span\");\n      age.textContent = ago(u.timestamp);\n      if (current === \"notBack\" && (Date.now() / 1000 - u.timestamp) > 2 * 365 * 86400) age.className = \"old\";\n      s.append(`${v.since} ${fmtDate(u.timestamp)} \u00b7 `, age);\n      who.append(s);\n    }\n\n    const open = document.createElement(\"a\");\n    open.className = \"btn\";\n    open.href = \"https://www.instagram.com/\" + encodeURIComponent(u.username) + \"/\";\n    open.target = \"_blank\";\n    open.rel = \"noopener\";\n    open.textContent = \"Open\";\n    open.setAttribute(\"aria-label\", \"Open @\" + u.username + \" on Instagram\");\n\n    li.append(who, open);\n\n    if (v.markable) {\n      const b = document.createElement(\"button\");\n      b.type = \"button\";\n      b.className = \"btn mark\";\n      b.textContent = current === \"gone\" ? \"Restore\" : \"Mark gone\";\n      b.addEventListener(\"click\", () => toggleGone(u.username));\n      li.append(b);\n    }\n    list.append(li);\n  }\n}\n\n// ---------- events ----------\nfor (const k of Object.keys(VIEWS)) {\n  $(\"t-\" + k).addEventListener(\"click\", () => { current = k; $(\"q\").value = \"\"; render(); });\n}\n$(\"q\").addEventListener(\"input\", render);\n$(\"sort\").addEventListener(\"change\", render);\n\n$(\"file\").addEventListener(\"change\", e => {\n  if (e.target.files.length) handleFiles([...e.target.files]);\n  e.target.value = \"\";\n});\n\nconst drop = $(\"drop\");\ndrop.addEventListener(\"dragover\", e => { e.preventDefault(); drop.classList.add(\"over\"); });\ndrop.addEventListener(\"dragleave\", () => drop.classList.remove(\"over\"));\ndrop.addEventListener(\"drop\", e => {\n  e.preventDefault();\n  drop.classList.remove(\"over\");\n  if (e.dataTransfer.files.length) handleFiles([...e.dataTransfer.files]);\n});\n\nlet clearArmed = false;\n$(\"clear\").addEventListener(\"click\", () => {\n  if (!clearArmed) {\n    clearArmed = true;\n    $(\"clear\").textContent = \"Tap again to clear\";\n    setTimeout(() => { clearArmed = false; $(\"clear\").textContent = \"Clear saved data\"; }, 4000);\n    return;\n  }\n  try { localStorage.removeItem(KEY); } catch (e) {}\n  clearArmed = false;\n  $(\"clear\").textContent = \"Clear saved data\";\n  state = makeDemo();\n  current = \"notBack\";\n  setStatus(\"Saved data cleared.\", \"ok\");\n  render();\n});\n\nrender();\n</script>\n</body>\n</html>\n";
const FAVICON = "<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 64 64\">\n  <defs><linearGradient id=\"g\" x1=\"0\" y1=\"0\" x2=\"1\" y2=\"1\"><stop offset=\"0\" stop-color=\"#3a74e0\"/><stop offset=\"1\" stop-color=\"#1f4fae\"/></linearGradient></defs>\n  <rect width=\"64\" height=\"64\" rx=\"15\" fill=\"url(#g)\"/>\n  <circle cx=\"25\" cy=\"30\" r=\"12.5\" fill=\"none\" stroke=\"#fff\" stroke-opacity=\".5\" stroke-width=\"4.5\"/>\n  <circle cx=\"39\" cy=\"30\" r=\"12.5\" fill=\"none\" stroke=\"#fff\" stroke-width=\"4.5\"/>\n  <circle cx=\"45\" cy=\"45\" r=\"10\" fill=\"#198a57\" stroke=\"#1f4fae\" stroke-width=\"3\"/>\n  <path d=\"M40.5 45.2l3.2 3.2 6-6.4\" fill=\"none\" stroke=\"#fff\" stroke-width=\"3\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/>\n</svg>";
const OG_PNG = "";
const APPLE_PNG = "";

function png(b64) {
  return Uint8Array.from(atob(b64), c => c.charCodeAt(0));
}

export default {
  async fetch(req) {
    const url = new URL(req.url);
    if (url.hostname === "www.thefollowcheck.com") {
      url.hostname = "thefollowcheck.com";
      return Response.redirect(url.toString(), 301);
    }
    const cache = { "cache-control": "public, max-age=86400" };
    if (url.pathname === "/favicon.svg") return new Response(FAVICON, { headers: { "content-type": "image/svg+xml", ...cache } });
    if (url.pathname === "/og.png") return new Response(png(OG_PNG), { headers: { "content-type": "image/png", ...cache } });
    if (url.pathname === "/apple-touch-icon.png") return new Response(png(APPLE_PNG), { headers: { "content-type": "image/png", ...cache } });
    if (url.pathname !== "/") return new Response("Not found", { status: 404 });
    return new Response(HTML, {
      headers: {
        "content-type": "text/html; charset=utf-8",
        "cache-control": "public, max-age=300",
        "x-content-type-options": "nosniff",
        "referrer-policy": "strict-origin-when-cross-origin"
      }
    });
  }
};
